		super.sql.append("      ,KB.KEI_TERM " + "\n");
		super.sql.append("      ,INVIO_FUNC.KAI_KEIK_TERM_RET(KB.KNSHU_YMD, TO_CHAR(TO_DATE(LEAST(END_YMD, KB.MRYO_YMD, NVL(TO_CHAR(TO_DATE(KB.KAI_YMD, 'YYYYMMDD') - 1, 'YYYYMMDD'), '99999999')), 'YYYYMMDD') + 1, 'YYYYMMDD')) KEI_PAST " + "\n");
		super.sql.append("      ,KB.TAISHO_AC_KIJYUN_CD " + "\n");
		super.sql.append("      ,KB.CTSHK_FLG " + "\n");
		super.sql.append("      ,KB.TY_YSU " + "\n");
