		super.sql.append("      ,KB.RSK_KEIJ_HOHO_KBN RSK_KEIJ_HOHO_KBN " + "\n");
		super.sql.append("      ,(SELECT RSK_KEIJ_HOHO_KBN_NM FROM M_RSK_KEIJ_HOHO_KBN TMP WHERE TMP.RSK_KEIJ_HOHO_KBN = KB.RSK_KEIJ_HOHO_KBN) RSK_KEIJ_HOHO_KBN_NM " + "\n");
		super.sql.append("      ,KB.TNKI_HOHO_KBN " + "\n");
		super.sql.append("      ,(SELECT FKN_TNKI_HOHO_NM FROM M_FKN_TNKI_HOHO_CD TMP WHERE TMP.FKN_TNKI_HOHO_CD = KB.TNKI_HOHO_KBN) TNKI_HOHO_KBN_NM " + "\n");
		// 20200604 arai 維持管理費対応 start
		super.sql.append("      ,KB.IJI_KNRI_HYO_JYO_KBN IJI_KNRI_HYO_JYO_KBN " + "\n");
		super.sql.append("      ,DECODE(IJI_KNRI_HYO_JYO_KBN, '1', 'あり', 'なし') IJI_KNRI_HYO_JYO_KBN_NM " + "\n");
		// 20200604 arai 維持管理費対応 end
		super.sql.append("      ,CASE " + "\n");
		super.sql.append("           WHEN KB.RSK_KEIJ_HOHO_KBN = '201' THEN " + "\n");
		super.sql.append("               '0' " + "\n");
		super.sql.append("           ELSE " + "\n");
		super.sql.append("               KB.EKM_TEIK_HYO_JYO_KBN " + "\n");
		super.sql.append("       END EKM_TEIK_HYO_JYO_KBN " + "\n");
		super.sql.append("      ,CASE " + "\n");
