		super.sql.append("               'なし' " + "\n");
		super.sql.append("           ELSE " + "\n");
		super.sql.append("               DECODE(EKM_TEIK_HYO_JYO_KBN, '1', 'あり', 'なし') " + "\n");
		super.sql.append("       END EKM_TEIK_HYO_JYO_KBN_NM " + "\n");
		super.sql.append("      ,FKN_TNKI_CHSE_CD " + "\n");
