		super.sql.append("      ,GNKSK_HASU_CHSE_CD " + "\n");
		super.sql.append("      ,(SELECT HASU_CHSE_NM FROM M_HASU_CHSE_CD TMP WHERE TMP.HASU_CHSE_CD = KB.GNKSK_HASU_CHSE_CD) GNKSK_HASU_CHSE_CD_NM " + "\n");
		super.sql.append("      ,KB.KEI_AMT + CASE " + "\n");
		super.sql.append("           WHEN (KB.ZANK_HSHOSK_CD = KB.LU_TRSK_CD) " + "\n");
		super.sql.append("           OR   (KB.IPN_ZANK_HSHOSK_CD = KB.LU_TRSK_CD) THEN " + "\n");
		super.sql.append("               KB.ZANK_HSHO_AMT " + "\n");
		super.sql.append("           ELSE " + "\n");
		super.sql.append("               0 " + "\n");
		super.sql.append("       END KEI_AMT " + "\n");
		super.sql.append("      ,KB.KEI_AMT_STAX KEI_TAX " + "\n");
		super.sql.append("      ,CASE KB.RSK_KEIJ_HOHO_KBN " + "\n");
		super.sql.append("           WHEN '101' THEN " + "\n");
		super.sql.append("               KB.MBRI_WRBK_PV " + "\n");
		super.sql.append("           ELSE " + "\n");
		super.sql.append("               KB.ABRI_WRBK_PV " + "\n");
		super.sql.append("       END WRBK_PV " + "\n");
		super.sql.append("      ,CASE KB.RSK_KEIJ_HOHO_KBN " + "\n");
