		super.sql.append("           ELSE " + "\n");
		super.sql.append("               KB.ABRI_WRBK_CLC_RS_RT " + "\n");
		super.sql.append("       END WRBK_RS_RT " + "\n");
		super.sql.append("      ,KB.KNU_AMT " + "\n");
