		super.sql.append("      ,TRUNC(KB.KEI_AMT / KB.KEI_TERM) MONTH_AMT " + "\n");
		super.sql.append("      ,TRUNC(KB.KEI_AMT_STAX / KB.KEI_TERM) MONTH_AMT_TAX " + "\n");
		super.sql.append("      ,TRUNC(NVL((SELECT (FKN_TNKI_D.GNPN_TTL - FKN_TNKI.SOU_USER_ZANK)" + "\n");
		super.sql.append("                  FROM   T_UKB_TNKI_HEAD   FKN_TNKI " + "\n");
		super.sql.append("                        ,T_UKB_TNKI_DETAIL FKN_TNKI_D " + "\n");
		super.sql.append("                  WHERE  FKN_TNKI.LC_CD = KB.LC_CD " + "\n");
		super.sql.append("                  AND    FKN_TNKI.KEI_NO = KB.KEI_NO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.BKN_NO = KB.BKN_NO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.BKN_EDANO = KB.BKN_EDANO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.LC_CD = FKN_TNKI_D.LC_CD " + "\n");
		super.sql.append("                  AND    FKN_TNKI.KEI_NO = FKN_TNKI_D.KEI_NO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.BKN_NO = FKN_TNKI_D.BKN_NO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.BKN_EDANO = FKN_TNKI_D.BKN_EDANO " + "\n");
		super.sql.append("                  AND    FKN_TNKI.KEIJ_YM = FKN_TNKI_D.KEIJ_YM " + "\n");
		super.sql.append("                  AND    FKN_TNKI_D.KEIJ_HOHO_KBN = KB.RSK_KEIJ_HOHO_KBN " + "\n");
		super.sql.append("                  AND    FKN_TNKI.KI = (SELECT MAX(KI)  FROM T_UKB_TNKI_HEAD WHERE KEI_NO = KB.KEI_NO AND KAI_REC_FLG = 0)), 0) / KB.KEI_TERM) MONTH_KINTO " + "\n");
		super.sql.append("      ,NVL((SELECT SUM(FKN_TNKI.LAMT) " + "\n");
		super.sql.append("            FROM   T_UKB_TNKI_HEAD FKN_TNKI " + "\n");
