		super.sql.append("            AND    FKN_TNKI.KEIJ_YM BETWEEN KB.START_KEIJ_YM AND KB.FKN_KEIJ_YM_LAST), 0) LAMT_STAX " + "\n");
		super.sql.append("      ,NVL((SELECT SUM(FKN_TNKI_D.TGTU_GNPN) " + "\n");
