		super.sql.append("            AND    FKN_TNKI_D.KEIJ_HOHO_KBN = KB.RSK_KEIJ_HOHO_KBN), 0) TGTU_RSK " + "\n");
		// 20200604 arai 維持管理費対応 start
		super.sql.append("      ,NVL((SELECT " + "\n");
		super.sql.append("                   SUM(FKN_TNKI.ENT_SHOHYO_KZI) " + "\n");
		super.sql.append("            FROM   T_UKB_TNKI_HEAD FKN_TNKI " + "\n");
